import React, { useState } from "react";
import "./ClientsList.css";

const Clients = [ // Simulación de datos temporal hasta conectar con API
  { id: 1, title: "Cliente 1" },
  { id: 2, title: "Cliente 2" },
  { id: 3, title: "Cliente 3" },
];

const ClientsList = () => {
  const [query, setQuery] = useState("");
  const [clientFilters, setClientFilters] = useState({});
  const [activeClient, setActiveClient] = useState(null);

  const filteredClients = Clients.filter((c) =>
    c.title.toLowerCase().includes(query.toLowerCase())
  );

  const applyClientFilters = (client) => {
    const filters = clientFilters[client.id];

    if (!filters) return client.invoices;
    let results = [...client.invoices];

    if (filters.dateFrom && filters.dateTo) {
      results = results.filter((inv) => {
        const date = new Date(inv.date);
        return (
          date >= new Date(filters.dateFrom) &&
          date <= new Date(filters.dateTo)
        );
      });
    }

    return results;
  };

  const handleFilterChange = (clientId, field, value) => {
    const newFilters = {
      ...clientFilters,
      [clientId]: {
        ...clientFilters[clientId],
        [field]: value,
      },
    };

    setClientFilters(newFilters);
  };

return (
  <div className="clients-container">
    <h2>Clientes</h2>

    <input
      type="text"
      placeholder="Buscar cliente..."
      value={query}
      onChange={(e) => setQuery(e.target.value)}
    />

    <div className="filters">
      <label>Rango de fechas</label>

      <input
        type="date"
        value={dateFrom}
        onChange={(e) => setDateFrom(e.target.value)}
      />

      <input
        type="date"
        value={dateTo}
        onChange={(e) => setDateTo(e.target.value)}
      />

      <label>Comparar con</label>

      <select
        value={compareWith}
        onChange={(e) => setCompareWith(e.target.value)}
      >
        <option value="">Sin elegir</option>
        <option value="previousMonth">
          Mes anterior
        </option>
        <option value="previousYear">
          Año anterior
        </option>
      </select>
    </div>

    {filteredClients.length === 0 ? (
      <p>No existen clientes</p>
    ) : (
      filteredClients.map((client) => (
        <div key={client.id} className="client-card">
          <h3>{client.title}</h3>

          <p>
            Facturas: {client.invoices.length}
          </p>

          <p>
            Total: $
            {client.invoices.reduce(
              (acc, inv) => acc + inv.amount,
              0
            )}
          </p>
        </div>
      ))
    )}
  </div>
);
};

export default ClientsList;
